@layer components {
  [data-skin="modern-apple"] :where([data-control-family="button"][data-control="true"]) {
    --cui-button-radius: var(--nest-radius, var(--radius-control));
    --cui-button-gap: 0.25rem;
    --cui-button-icon: 0.9375rem;
    --cui-button-padding-inline: 0.6875rem;
    --cui-button-font-size: var(--text-body);
    --cui-button-font-weight: 400;
    --cui-button-press-scale: 1;
  }

  [data-skin="modern-apple"] :where([data-control-family="button"][data-control="true"][data-size="xs"]) {
    --cui-button-radius: var(--nest-radius, 0.3125rem);
    --cui-button-gap: 0.1875rem;
    --cui-button-icon: 0.8125rem;
    --cui-button-padding-inline: 0.625rem;
    --cui-button-font-size: var(--text-caption);
  }

  [data-skin="modern-apple"] :where([data-control-family="button"][data-control="true"][data-size="md"]) {
    --cui-button-radius: var(--nest-radius, 9999px);
    --cui-button-icon: 1rem;
    --cui-button-padding-inline: 0.875rem;
  }

  [data-skin="modern-apple"] :where([data-control-family="button"][data-control="true"][data-size="lg"]) {
    --cui-button-radius: var(--nest-radius, 9999px);
    --cui-button-gap: 0.375rem;
    --cui-button-icon: 1.125rem;
    --cui-button-padding-inline: 1.125rem;
  }

  [data-skin="modern-apple"]
    :where([data-control-family="button"][data-control="true"]:is([data-variant="ghost"], [data-variant="quiet"])) {
    --cui-button-press-background: var(--active-fill);
    --cui-button-active-background: var(--active-fill);
    --cui-button-active-foreground: var(--foreground);
    --cui-button-active-hover-background: var(--active-fill);
  }

  [data-skin="modern-apple"] :where([data-control-family="button"][data-control="true"][data-variant="surface"]) {
    --cui-button-background: var(--apple-fill);
    --cui-button-hover-background: var(--apple-fill);
    --cui-button-press-background: var(--apple-fill-pressed);
    --cui-button-open-background: var(--apple-fill-pressed);
    --cui-button-shadow: 0 0 transparent;
    --cui-button-active-background: var(--primary);
    --cui-button-active-foreground: var(--primary-foreground);
    --cui-button-active-hover-background: var(--primary);
    --cui-button-active-shadow: 0 0 transparent;
  }

  [data-skin="modern-apple"] :where([data-control-family="button"][data-control="true"][data-variant="solid"]) {
    --cui-button-hover-background: var(--cui-button-background);
    --cui-button-press-background: oklch(from var(--cui-button-background) calc(l - 0.07) c h);
    --cui-button-active-hover-background: var(--cui-button-background);
    --cui-button-shadow: 0 0 transparent;
  }

  [data-skin="modern-apple"] :where([data-control-family="field"][data-control="true"]) {
    --cui-field-radius: var(--nest-radius, var(--radius-control));
    --cui-field-background: var(--apple-field-fill);
    --cui-field-hover-background: var(--apple-field-fill);
    --cui-field-foreground: var(--foreground);
    --cui-field-border-color: var(--input);
    --cui-field-border-width: 1px;
    --cui-field-shadow: 0 0 transparent;
    --cui-field-backdrop-filter: none;
    --cui-field-height: var(--control-h-sm);
    --cui-field-padding-inline: 0.4375rem;
    --cui-field-font-size: var(--text-body);
    --cui-field-font-weight: 400;
    --cui-field-affordance-foreground: var(--foreground);
    --cui-field-affordance-background: var(--apple-fill);
    --cui-field-affordance-hover-background: var(--apple-fill-pressed);
    --focus-ring-offset: 0px;
  }

  [data-skin="modern-apple"] :where([data-control-family="field"][data-control="true"][data-size="xs"]) {
    --cui-field-height: var(--control-h-xs);
    --cui-field-radius: var(--nest-radius, 0.3125rem);
    --cui-field-padding-inline: 0.375rem;
    --cui-field-font-size: var(--text-caption);
  }

  [data-skin="modern-apple"] :where([data-control-family="field"][data-control="true"][data-size="lg"]) {
    --cui-field-height: var(--control-h);
    --cui-field-radius: var(--nest-radius, 0.4375rem);
    --cui-field-padding-inline: 0.5625rem;
  }

  [data-skin="modern-apple"]
    :where([data-control-family="field"][data-control="true"]:is([data-field-kind="select"], [data-field-kind="native-select"])) {
    --cui-field-background: var(--apple-fill);
    --cui-field-hover-background: var(--apple-fill);
    --cui-field-border-width: 0px;
    --cui-field-padding-inline: 0.6875rem;
    --cui-field-affordance-background: transparent;
  }

  [data-skin="modern-apple"] :where([data-control-family="field"][data-field-kind="field"]) {
    --cui-field-label-font-size: var(--text-body);
    --cui-field-description-font-size: var(--text-caption);
    --cui-field-group-radius: var(--radius);
    --cui-field-group-background: var(--apple-box-fill);
    --cui-field-group-border-color: var(--apple-box-edge);
  }

  [data-skin="modern-apple"]
    :where(
      [data-control-family="choice"][data-choice-kind="checkbox"][data-slot="root"],
      [data-control-family="choice"][data-choice-kind="radio-group"][data-slot="item"]
    ) {
    --cui-choice-background: var(--apple-fill-strong);
    --cui-choice-border-width: 0px;
    --cui-choice-checked-border-color: transparent;
    --cui-choice-shadow: 0 0 transparent;
  }

  [data-skin="modern-apple"] :where([data-control-family="choice"][data-choice-kind="checkbox"][data-slot="root"]) {
    --cui-choice-radius: 0.3125rem;
  }

  [data-skin="modern-apple"] :where([data-control-family="switch"][data-slot="root"]) {
    --cui-switch-inline-size: 3.375rem;
    --cui-switch-height: 1.5rem;
    --cui-switch-thumb-inline-size: 2rem;
    --cui-switch-padding: 0.125rem;
    --cui-switch-border-width: 0px;
    --cui-switch-background: var(--apple-fill-strong);
    --cui-switch-hover-background: var(--apple-fill-strong);
    --cui-switch-checked-hover-background: var(--primary);
    --cui-switch-thumb-background: var(--apple-knob);
    --cui-switch-thumb-shadow: var(--apple-knob-shadow);
    --cui-switch-thumb-press-scale: 1.12 1.2;
    --cui-switch-thumb-press-inline-size: var(--cui-switch-thumb-inline-size);
  }

  [data-skin="modern-apple"] :where([data-control-family="switch"][data-slot="root"]:is(:active, [data-dragging])) {
    --cui-switch-background: var(--apple-fill-pressed);
    --cui-switch-checked-background: oklch(from var(--primary) calc(l * 0.95) c h);
  }

  @supports (backdrop-filter: blur(1px)) {
    [data-skin="modern-apple"]
      :where([data-control-family="switch"][data-slot="root"]:is(:active, [data-dragging]):not([data-disabled], [data-readonly])) {
      --cui-switch-thumb-background: oklch(1 0 0 / 0.3);
      --cui-switch-thumb-backdrop-filter: blur(2px) saturate(1.5);
      --cui-switch-thumb-shadow:
        inset 0 0 0 1px oklch(1 0 0 / 0.65), inset 0 1px 1px oklch(1 0 0 / 0.9), inset 0 -1px 2px oklch(0 0 0 / 0.15),
        0 2px 8px oklch(0 0 0 / 0.15);
    }
  }

  @media (prefers-reduced-transparency: reduce), (forced-colors: active) {
    [data-skin="modern-apple"] :where([data-control-family="switch"][data-slot="root"]:is(:active, [data-dragging])) {
      --cui-switch-thumb-background: var(--apple-knob);
      --cui-switch-thumb-backdrop-filter: none;
    }
  }

  [data-skin="modern-apple"] :where([data-control-family="range"][data-slot="root"]) {
    --cui-range-track-background: var(--apple-track);
    --cui-range-indicator-background: var(--primary);
  }

  [data-skin="modern-apple"] :where([data-control-family="range"][data-range-kind="slider"][data-slot="root"]:not([data-variant="plain"])) {
    --cui-range-track-background: var(--apple-fill-strong);
    --cui-range-thumb-background: var(--apple-knob);
    --cui-range-thumb-border-color: transparent;
    --cui-range-thumb-shadow: var(--apple-knob-shadow);
    --cui-range-thumb-inline-size: 1.25rem;
    --cui-range-thumb-block-size: 1rem;
  }

  [data-skin="modern-apple"] :where([data-slot="root"][data-control-family="tabs"]) {
    --cui-tabs-trigger-radius: 0.4375rem;
    --cui-tabs-list-padding: 0.0625rem;
    --cui-tabs-list-background: var(--apple-fill);
    --cui-tabs-list-shadow: none;
    --cui-tabs-list-backdrop-filter: none;
    --cui-tabs-indicator-background: var(--apple-raised);
    --cui-tabs-indicator-shadow: var(--apple-raised-shadow);
    --cui-tabs-foreground: var(--foreground);
    --cui-tabs-hover-foreground: var(--foreground);
    --cui-tabs-active-foreground: var(--foreground);
    --cui-tabs-font-size: var(--text-body);
    --cui-tabs-font-weight: 400;
    --cui-tabs-surface-background: var(--apple-box-fill);
    --cui-tabs-border-color: var(--apple-box-edge);
  }

  [data-skin="modern-apple"] :where([data-control-family="tabs"][data-slot="list"]) {
    --cui-tabs-trigger-height: calc(var(--control-h-sm) - 2 * var(--cui-tabs-list-padding));
  }

  [data-skin="modern-apple"] :where([data-control-family="tabs"][data-slot="list"][data-size="xs"]) {
    --cui-tabs-trigger-height: calc(var(--control-h-xs) - 2 * var(--cui-tabs-list-padding));
  }

  [data-skin="modern-apple"] :where([data-control-family="tabs"][data-slot="list"][data-size="md"]) {
    --cui-tabs-trigger-height: calc(var(--control-h-md) - 2 * var(--cui-tabs-list-padding));
  }

  [data-skin="modern-apple"] :where([data-control-family="tabs"][data-slot="list"][data-size="lg"]) {
    --cui-tabs-trigger-height: calc(var(--control-h-lg) - 2 * var(--cui-tabs-list-padding));
  }
}

@layer components {
  [data-skin="modern-apple"]
    :where(
      [data-control-family="popup"][data-popup-part="surface"],
      [data-control-family="popup"][data-popup-part="list-surface"],
      [data-control-family="popup"][data-popup-part="bar"]
    ) {
    --cui-popup-border-width: 0px;
    --cui-popup-title-font-size: var(--text-heading-4);
    --cui-popup-title-font-weight: 700;
    --cui-popup-title-line-height: var(--text-heading-4--line-height);
    --cui-popup-title-letter-spacing: 0em;
    --cui-popup-item-font-size: var(--text-body);
    --cui-popup-item-icon-size: 0.9375rem;
    --cui-popup-item-min-height: 1.5rem;
    --cui-popup-item-padding-block: 0.125rem;
    --cui-popup-item-padding-inline: 0.5625rem;
    --cui-popup-item-inset: 1.5625rem;
    --cui-popup-item-highlight-background: var(--primary);
    --cui-popup-item-highlight-foreground: var(--primary-foreground);
    --cui-popup-item-highlight-muted-foreground: var(--primary-foreground);
    --cui-popup-item-highlight-shadow: 0 0 transparent;
    --cui-popup-item-disabled-opacity: 0.3;
    --cui-popup-label-padding-block: 0.25rem 0.125rem;
    --cui-popup-label-font-size: var(--text-caption);
    --cui-popup-label-font-weight: 700;
    --cui-popup-label-letter-spacing: 0em;
    --cui-popup-label-text-transform: none;
    --cui-popup-command-heading-font-size: var(--text-caption);
    --cui-popup-command-heading-letter-spacing: 0em;
    --cui-popup-command-heading-text-transform: none;
    --cui-popup-separator-color: var(--apple-separator);
    --cui-popup-separator-inset: 0.5625rem;
    --cui-popup-separator-gap: 0.3125rem;
    --cui-popup-shortcut-font-size: var(--text-body);
    --cui-popup-shortcut-letter-spacing: 0.04em;
  }

  [data-skin="modern-apple"]
    :where(
      [data-control-family="popup"][data-slot][data-popup-part="surface"][data-surface="floating"]:not([data-popup-kind="tooltip"]),
      [data-control-family="popup"][data-slot][data-popup-part="list-surface"][data-surface="floating"],
      [data-control-family="popup"][data-slot][data-popup-part="surface"][data-surface="modal"]
    ) {
    --cui-popup-radius: var(--radius-popover);
    --cui-popup-background: var(--apple-glass-fill);
    --cui-popup-shadow: var(--apple-menu-shadow);
    --cui-popup-backdrop-filter: var(--apple-glass-filter);
  }

  [data-skin="modern-apple"]
    :where(
      [data-control-family="popup"][data-slot][data-popup-part="surface"][data-surface="floating"]:is(
        [data-popup-kind="popover"],
        [data-popup-kind="hover-card"],
        [data-popup-kind="rich-tooltip"],
        [data-popup-kind="color-picker"]
      )
    ) {
    --cui-popup-radius: 1.25rem;
    --cui-popup-shadow: var(--apple-popover-shadow);
  }

  [data-skin="modern-apple"] :where([data-control-family="popup"][data-slot][data-popup-part="surface"][data-surface="modal"]) {
    --cui-popup-radius: var(--radius-scene);
    --cui-popup-background: var(--background);
    --cui-popup-backdrop-filter: none;
    --cui-popup-shadow: var(--apple-window-shadow);
    --cui-popup-description-foreground: var(--foreground);
  }

  [data-skin="modern-apple"]
    :where([data-control-family="popup"][data-slot][data-popup-part="surface"][data-surface="modal"][data-popup-kind="alert-dialog"]) {
    --cui-popup-radius: 1.625rem;
    --cui-popup-background: var(--apple-glass-fill);
    --cui-popup-backdrop-filter: var(--apple-glass-filter);
    --cui-popup-dialog-max-inline-size: 16.25rem;
  }

  [data-skin="modern-apple"]
    :where(
      [data-control-family="popup"][data-popup-kind="alert-dialog"][data-slot="footer"]
        > [data-control-family="button"][data-control="true"]
    ) {
    --cui-button-height: var(--control-h-lg);
    --cui-button-radius: var(--nest-radius, 9999px);
    flex: 1 1 0;
  }

  [data-skin="modern-apple"] :where([data-control-family="popup"][data-popup-kind="tooltip"][data-popup-part="surface"]) {
    --cui-popup-radius: 0.3125rem;
    --cui-popup-background: var(--apple-tooltip);
    --cui-popup-foreground: var(--apple-tooltip-foreground);
    --cui-popup-shadow: var(--apple-tooltip-shadow);
    --cui-popup-backdrop-filter: none;
    font-size: var(--text-caption);
  }

  [data-skin="modern-apple"] :where([data-control-family="popup"][data-popup-kind="toast"][data-popup-part="surface"]) {
    --cui-popup-radius: 1.125rem;
  }

  [data-skin="modern-apple"] :where([data-control-family="popup"][data-popup-part="backdrop"]) {
    --cui-popup-backdrop-blur: 0px;
  }

  [data-skin="modern-apple"] :where([data-slot="root"][data-control-family="card"]) {
    --cui-card-background: var(--apple-box-fill);
    --cui-card-border-color: var(--apple-box-edge);
    --cui-card-shadow: none;
  }

  [data-skin="modern-apple"] :where([data-slot="root"][data-control-family="table"]) {
    --cui-table-border-color: var(--apple-separator);
    --cui-table-row-hover-background: transparent;
    --cui-table-row-selected-background: var(--apple-selection-unemphasized);
    --cui-table-header-foreground: var(--muted-foreground);
  }

  [data-skin="modern-apple"] :where([data-slot="root"][data-control-family="tree"]) {
    --cui-tree-item-trigger-radius: 0.375rem;
    --cui-tree-item-trigger-font-size: var(--text-body);
    --cui-tree-item-trigger-hover-background: transparent;
    --cui-tree-item-trigger-selected-background: var(--apple-selection-unemphasized);
    --cui-tree-item-trigger-selected-foreground: var(--foreground);
  }

  [data-skin="modern-apple"] :where([data-slot="root"][data-control-family="tree"]:focus-within) {
    --cui-tree-item-trigger-selected-background: var(--apple-selection);
    --cui-tree-item-trigger-selected-foreground: var(--primary-foreground);
  }
}

import type { ControlUiSkin } from "@/components/control-ui/skin";

export const skin: ControlUiSkin = {
  id: "modern-apple",
  sidebarLayout: "sidebar",
  scrollAreaBlur: true,
  selectAlignItemWithTrigger: true,
};

@import "./modern-apple-controls.css";
@import "./modern-apple-surfaces.css";

[data-skin="modern-apple"] {
  --apple-fill: oklch(0 0 0 / 0.075);
  --apple-fill-strong: oklch(0 0 0 / 0.1);
  --apple-fill-pressed: oklch(0 0 0 / 0.16);
  --apple-track: oklch(0 0 0 / 0.06);
  --apple-box-fill: oklch(0 0 0 / 0.031);
  --apple-box-edge: oklch(0 0 0 / 0.075);
  --apple-field-fill: oklch(1 0 0 / 0.85);
  --apple-knob: oklch(1 0 0);
  --apple-raised: oklch(1 0 0);
  --apple-knob-shadow: 0 0 0 0.5px oklch(0 0 0 / 0.06), 0 1px 2.5px oklch(0 0 0 / 0.16), 0 3px 8px oklch(0 0 0 / 0.08);
  --apple-raised-shadow: 0 0 0 0.5px oklch(0 0 0 / 0.08), 0 1px 2.5px oklch(0 0 0 / 0.14);
  --apple-selection: oklch(0.575 0.217 258.4);
  --apple-selection-unemphasized: oklch(0 0 0 / 0.1);
  --apple-separator: oklch(0 0 0 / 0.1);
  --apple-tooltip: oklch(0.913 0 0);
  --apple-tooltip-foreground: oklch(0.387 0 0);
  --apple-sidebar-material: oklch(0.942 0 0 / 0.95);
  --apple-sidebar-backdrop-filter: blur(40px) saturate(1.6);
  --apple-sidebar-icon: var(--primary);
  --apple-glass-refraction: blur(0px);
  --apple-glass-fill: oklch(from var(--popover) l c h / var(--popover-opacity));
  --apple-glass-filter: blur(var(--backdrop-blur-popover)) saturate(1.8) var(--apple-glass-refraction);
  --apple-glass-rim: 0 0 0 0.5px oklch(0 0 0 / 0.12), inset 0 0 0 1px oklch(1 0 0 / 0.45);
  --apple-menu-shadow: var(--apple-glass-rim), 0 2px 6px oklch(0 0 0 / 0.1), 0 8px 24px oklch(0 0 0 / 0.14);
  --apple-popover-shadow: var(--apple-glass-rim), 0 4px 16px oklch(0 0 0 / 0.1);
  --apple-window-shadow: 0 0 0 0.5px oklch(0 0 0 / 0.16), 0 8px 20px oklch(0 0 0 / 0.12), 0 22px 60px oklch(0 0 0 / 0.22);
  --apple-tooltip-shadow: 0 0 0 0.5px oklch(0 0 0 / 0.12), 0 2px 6px oklch(0 0 0 / 0.14);
  --apple-platter-shadow: var(--apple-glass-rim), 0 1px 4px oklch(0 0 0 / 0.08), 0 4px 14px oklch(0 0 0 / 0.08);
}

@supports (backdrop-filter: url("")) {
  [data-skin="modern-apple"]:has(#cui-modern-apple-refraction),
  :root:has(#cui-modern-apple-refraction) [data-skin="modern-apple"] {
    --apple-glass-refraction: url("#cui-modern-apple-refraction");
  }
}

:where(.dark) [data-skin="modern-apple"],
.dark[data-skin="modern-apple"] {
  --apple-fill: oklch(1 0 0 / 0.075);
  --apple-fill-strong: oklch(1 0 0 / 0.1);
  --apple-fill-pressed: oklch(1 0 0 / 0.16);
  --apple-track: oklch(1 0 0 / 0.08);
  --apple-box-fill: oklch(1 0 0 / 0.035);
  --apple-box-edge: oklch(1 0 0 / 0.08);
  --apple-field-fill: oklch(0 0 0 / 0.22);
  --apple-knob: oklch(0.88 0 0);
  --apple-raised: oklch(0.47 0 0);
  --apple-knob-shadow: 0 0 0 0.5px oklch(0 0 0 / 0.2), 0 1px 2.5px oklch(0 0 0 / 0.35), 0 3px 8px oklch(0 0 0 / 0.2);
  --apple-raised-shadow: 0 0 0 0.5px oklch(0 0 0 / 0.3), 0 1px 2.5px oklch(0 0 0 / 0.3);
  --apple-selection: var(--primary);
  --apple-selection-unemphasized: oklch(1 0 0 / 0.12);
  --apple-separator: oklch(1 0 0 / 0.12);
  --apple-tooltip: oklch(0.39 0 0);
  --apple-tooltip-foreground: oklch(0.943 0 0);
  --apple-sidebar-material: oklch(0.274 0.002 248 / 0.95);
  --apple-glass-rim: 0 0 0 0.5px oklch(0 0 0 / 0.6), inset 0 0 0 1px oklch(1 0 0 / 0.12);
  --apple-menu-shadow: var(--apple-glass-rim), 0 2px 6px oklch(0 0 0 / 0.25), 0 8px 24px oklch(0 0 0 / 0.35);
  --apple-popover-shadow: var(--apple-glass-rim), 0 4px 16px oklch(0 0 0 / 0.3);
  --apple-window-shadow:
    0 0 0 0.5px oklch(0 0 0 / 0.7), inset 0 0 0 1px oklch(1 0 0 / 0.1), 0 8px 20px oklch(0 0 0 / 0.3), 0 22px 60px oklch(0 0 0 / 0.45);
  --apple-tooltip-shadow: 0 0 0 0.5px oklch(0 0 0 / 0.5), 0 2px 6px oklch(0 0 0 / 0.3);
  --apple-platter-shadow: var(--apple-glass-rim), 0 1px 4px oklch(0 0 0 / 0.25), 0 4px 14px oklch(0 0 0 / 0.2);
}

@layer components {
  [data-skin="modern-apple"] .apple-glass {
    background-color: var(--apple-glass-fill);
    -webkit-backdrop-filter: var(--apple-glass-filter);
    backdrop-filter: var(--apple-glass-filter);
    box-shadow: var(--apple-glass-rim);
  }

  [data-skin="modern-apple"] :where([data-slot="wrapper"][data-control-family="sidebar"]) {
    --cui-sidebar-wrapper-background-image: none;
    --cui-sidebar-inset-background: var(--background);
    --cui-sidebar-inset-background-image: none;
    --cui-sidebar-inset-shadow: none;
    --cui-sidebar-inset-border-width: 0px;
    --cui-sidebar-inset-radius: 0px;
    --cui-sidebar-inset-inset: 0px;
  }

  [data-skin="modern-apple"] :where([data-slot="root"][data-control-family="sidebar"]) {
    --sidebar: transparent;
    --cui-sidebar-inner-background: var(--apple-sidebar-material);
    --cui-sidebar-inner-backdrop-filter: var(--apple-sidebar-backdrop-filter);
    --cui-sidebar-inner-border-width: 0px;
    --cui-sidebar-inner-radius: 0px;
    --cui-sidebar-inner-shadow: none;
    --cui-sidebar-group-label-foreground: var(--muted-foreground);
    --cui-sidebar-group-label-font-size: var(--text-caption);
    --cui-sidebar-group-label-font-weight: 700;
    --cui-sidebar-menu-button-height: 1.5rem;
    --cui-sidebar-menu-button-radius: 0.4375rem;
    --cui-sidebar-menu-button-font-size: var(--text-body);
    --cui-sidebar-menu-button-font-weight: 400;
    --cui-sidebar-menu-button-active-font-weight: 600;
    --cui-sidebar-menu-button-foreground: var(--foreground);
    --cui-sidebar-menu-button-hover-background: transparent;
    --cui-sidebar-menu-button-hover-foreground: var(--foreground);
    --cui-sidebar-menu-button-active-background: var(--apple-selection-unemphasized);
    --cui-sidebar-menu-button-active-foreground: var(--foreground);
  }

  [data-skin="modern-apple"] :where([data-slot="root"][data-control-family="sidebar"]:focus-within) {
    --cui-sidebar-menu-button-active-background: var(--apple-selection);
    --cui-sidebar-menu-button-active-foreground: var(--primary-foreground);
  }

  [data-skin="modern-apple"] :where([data-slot="root"][data-control-family="sidebar"][data-variant="floating"][data-state]) {
    --cui-sidebar-inner-radius: var(--radius-scene);
    --cui-sidebar-inner-shadow: var(--apple-window-shadow);
  }

  [data-skin="modern-apple"]
    :where([data-control-family="sidebar"][data-slot="menu-button"], [data-control-family="sidebar"][data-slot="group-label"])
    > svg:first-child {
    color: var(--apple-sidebar-icon);
  }

  [data-skin="modern-apple"]
    :where(
      [data-control-family="sidebar"][data-slot="root"]:focus-within
        [data-control-family="sidebar"][data-slot="menu-button"]:is([data-active="true"], [aria-current="page"])
    )
    > svg:first-child {
    color: currentColor;
  }

  [data-skin="modern-apple"]
    :where([data-control-family="sidebar"][data-slot="menu-track"])
    > :where([data-control-family="track-highlight"][data-slot="root"]) {
    --cui-track-highlight-background: var(--cui-sidebar-menu-button-active-background);
    --cui-track-highlight-hover-background: var(--cui-sidebar-menu-button-hover-background);
    --cui-track-highlight-radius: var(--cui-sidebar-menu-button-radius);
    --cui-track-highlight-ring-color: transparent;
    --cui-track-highlight-shadow: none;
  }

  [data-skin="modern-apple"] :where([data-slot="root"][data-control-family="toolbar"]) {
    --cui-toolbar-padding: 0.25rem;
    --cui-toolbar-item-radius: 9999px;
    --cui-toolbar-background: var(--apple-glass-fill);
    --cui-toolbar-border-width: 0px;
    --cui-toolbar-shadow: var(--apple-platter-shadow);
    --cui-toolbar-item-foreground: var(--foreground);
    --cui-toolbar-item-hover-background: var(--hover-fill);
    --cui-toolbar-item-active-background: var(--apple-fill-strong);
    --cui-toolbar-separator-background: var(--apple-separator);
    -webkit-backdrop-filter: var(--apple-glass-filter);
    backdrop-filter: var(--apple-glass-filter);
  }

  [data-skin="modern-apple"] :where([data-slot="root"][data-control-family="toolbar"][data-chrome="embedded"]) {
    --cui-toolbar-background: transparent;
    --cui-toolbar-shadow: none;
  }

  [data-skin="modern-apple"]
    :where(
      [data-slot="root"][data-variant="inverse"][data-control-family="toolbar"]
        [data-control-ui="button"][data-slot="root"][data-control-family="button"]
    ) {
    --cui-button-background: transparent;
    --cui-button-foreground: oklch(from var(--background) l c h / 0.7);
    --cui-button-hover-background: oklch(from var(--background) l c h / 0.1);
    --cui-button-hover-foreground: var(--background);
    --cui-button-press-background: oklch(from var(--background) l c h / 0.12);
    --cui-button-active-background: var(--background);
    --cui-button-active-foreground: var(--foreground);
    --cui-button-active-hover-background: var(--background);
    --cui-button-shadow: 0 0 transparent;
    --cui-button-active-shadow: 0 0 transparent;
  }

  @media (prefers-reduced-transparency: reduce), (forced-colors: active) {
    [data-skin="modern-apple"] :where([data-control-family="sidebar"][data-slot="root"]) {
      --cui-sidebar-inner-background: oklch(from var(--apple-sidebar-material) l c h);
      --cui-sidebar-inner-backdrop-filter: none;
    }
  }

  [data-skin="modern-apple"] :where([data-slot="root"][data-control-family="thread-rail"]) {
    --cui-thread-rail-popover-radius: var(--radius-popover);
  }

  [data-skin="modern-apple"] :where([data-control-family="thread-rail"][data-slot="popover"][data-surface="floating"]) {
    --cui-thread-rail-popover-background: var(--apple-glass-fill);
    --cui-thread-rail-popover-border-width: 0px;
    --cui-thread-rail-popover-shadow: var(--apple-menu-shadow);
    --cui-thread-rail-popover-backdrop-blur: var(--backdrop-blur-popover);
  }

  [data-skin="modern-apple"] :where([data-slot="root"][data-layout="bubble"][data-control-family="chat-message"]) {
    --cui-chat-message-radius: 1.125rem;
    --cui-chat-message-corner-radius: 1.125rem;
    --cui-chat-message-shadow: none;
  }

  [data-skin="modern-apple"] :where([data-slot="root"][data-role="user"][data-layout="bubble"][data-control-family="chat-message"]) {
    --cui-chat-message-background: var(--primary);
    --cui-chat-message-foreground: var(--primary-foreground);
  }

  [data-skin="modern-apple"] :where([data-control-ui="chat-composer"][data-slot="root"][data-control-family="chat-composer"]) {
    --cui-chat-composer-shell-background: var(--apple-field-fill);
    --cui-chat-composer-shell-backdrop-filter: blur(var(--backdrop-blur-popover)) saturate(1.8);
    --cui-chat-composer-shell-border-color: var(--input);
    --cui-chat-composer-shell-shadow: none;
    --cui-chat-composer-input-foreground: var(--foreground);
  }

  [data-skin="modern-apple"] :where([data-slot="root"][data-control-family="markdown-block"]) {
    --cui-markdown-block-border-color: var(--apple-box-edge);
  }

  [data-skin="modern-apple"]
    :where([data-control-ui="chat-layout"][data-slot="root"][data-control-family="chat-layout"][data-chrome="panel"]) {
    --cui-chat-layout-background: var(--card);
    --cui-chat-layout-border-color: var(--border);
    --cui-chat-layout-shadow: none;
  }
}

